vulnerabilities.suggested_fix:
Wrap the permit call in a try-catch block and only revert if both the permit fails AND the current allowance is insufficient. This allows the unstake to proceed if allowance was already set (either by the front-runner's permit or a previous approval):

```solidity
function unstakeRequestWithPermit(...) external returns (uint256) {
    try mETH.permit(msg.sender, address(this), methAmount, deadline, v, r, s) {} catch {
        // If permit fails, check if allowance is already sufficient
        if (mETH.allowance(msg.sender, address(this)) < methAmount) {
            revert("Permit failed and insufficient allowance");
        }
    }
    return _unstakeRequest(methAmount, minETHAmount);
}
```

Modify recoverSapientSignature to return the actual imageHash recovered during signature validation. The signatureValidation function already recovers the imageHash via BaseSig.recover, so either: (1) extend signatureValidation to also return the imageHash, or (2) call BaseSig.recover directly in recoverSapientSignature and return the recovered imageHash. Example fix:

```solidity
function recoverSapientSignature(
    Payload.Decoded memory _payload,
    bytes calldata _signature
) external view returns (bytes32) {
    // ... existing parent wallet logic ...

    (,, bytes32 imageHash,,) = BaseSig.recover(_payload, _signature, false, address(0));

    if (!_isValidImage(imageHash)) {
        revert InvalidSapientSignature(_payload, _signature);
    }

    return imageHash;
}
```

Before attempting CREATE2 deployment, check if code already exists at the predicted address and return it if so:

```solidity
function deploy(address _mainModule, bytes32 _salt) public payable returns (address _contract) {
    bytes memory code = abi.encodePacked(Wallet.creationCode, uint256(uint160(_mainModule)));
    _contract = address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), address(this), _salt, keccak256(code))))));

    if (_contract.code.length > 0) {
        return _contract; // Already deployed, return existing address
    }

    assembly {
        _contract := create2(callvalue(), add(code, 32), mload(code), _salt)
    }
    if (_contract == address(0)) {
        revert DeployFailed(_mainModule, _salt);
    }
}
```

In `_checkpoint`, when recording user history, check if the latest user_point has the same timestamp as the current block.timestamp. If so, overwrite the existing point instead of creating a new epoch:

```solidity
uint user_epoch = votingBalanceLogicData.user_point_epoch[_tokenId];
if (user_epoch > 0 && votingBalanceLogicData.user_point_history[_tokenId][user_epoch].ts == block.timestamp) {
    // Overwrite existing point at same timestamp
    votingBalanceLogicData.user_point_history[_tokenId][user_epoch] = u_new;
} else {
    // Create new epoch
    user_epoch = user_epoch + 1;
    votingBalanceLogicData.user_point_epoch[_tokenId] = user_epoch;
    u_new.ts = block.timestamp;
    u_new.blk = block.number;
    votingBalanceLogicData.user_point_history[_tokenId][user_epoch] = u_new;
}
```
